    let oldLines = 0;
    let newLines = 0;
    for (let j = start; j < end; j++) {
      const { op, line } = script[j];
      if (op === 'equal') {
        lines.push(' ' + line);
        oldLines++;
        newLines++;
      } else if (op === 'delete') {
        lines.push('-' + line);
        oldLines++;
      } else {
        lines.push('+' + line);
        newLines++;
      }
