    for (let count = 0; start > 0 && count < context && script[start - 1].op === 'equal'; count++) start--;
    for (let count = 0; end < script.length && count < context && script[end].op === 'equal'; count++) end++;
    const previous = ranges[ranges.length - 1];
    if (previous && start <= previous[1]) previous[1] = Math.max(previous[1], end);
    else ranges.push([start, end]);
  }
