    const newOffset = before.filter(entry => entry.op !== 'delete').length;
    const oldLines = entries.filter(entry => entry.op !== 'insert').length;
    const newLines = entries.filter(entry => entry.op !== 'delete').length;
    return {
      oldStart: oldOffset + (oldLines ? 1 : 0), oldLines,
      newStart: newOffset + (newLines ? 1 : 0), newLines,
