'use strict';
const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const row = Array(b.length + 1).fill(0);
  for (const line of a) {
    let diagonal = 0;
    for (let j = 1; j <= b.length; j++) {
      const prior = row[j];
      row[j] = line === b[j - 1] ? diagonal + 1 : Math.max(row[j], row[j - 1]);
      diagonal = prior;
    }
  }
  return row[b.length];
}

function expectedHunks(script, context) {
  const ranges = [];
  for (let i = 0; i < script.length; i++) {
    if (script[i].op === 'equal') continue;
    let start = i;
    let end = i + 1;
    for (let count = 0; start > 0 && count < context && script[start - 1].op === 'equal'; count++) start--;
    for (let count = 0; end < script.length && count < context && script[end].op === 'equal'; count++) end++;
    const previous = ranges[ranges.length - 1];
    if (previous && start <= previous[1]) previous[1] = Math.max(previous[1], end);
    else ranges.push([start, end]);
  }
  return ranges.map(([start, end]) => {
    const before = script.slice(0, start);
    const entries = script.slice(start, end);
    const oldOffset = before.filter(entry => entry.op !== 'insert').length;
    const newOffset = before.filter(entry => entry.op !== 'delete').length;
    const oldLines = entries.filter(entry => entry.op !== 'insert').length;
    const newLines = entries.filter(entry => entry.op !== 'delete').length;
    return {
      oldStart: oldOffset + (oldLines ? 1 : 0), oldLines,
      newStart: newOffset + (newLines ? 1 : 0), newLines,
      lines: entries.map(entry => ({ equal: ' ', delete: '-', insert: '+' })[entry.op] + entry.line),
    };
  });
}

const arrays = [Object.freeze([])];
let level = [[]];
for (let length = 1; length <= 4; length++) {
  level = level.flatMap(prefix => ['', '-', '+'].map(line => Object.freeze([...prefix, line])));
  arrays.push(...level);
}
let pairs = 0;
for (const a of arrays) for (const b of arrays) {
  const script = diffLines(a, b);
  assert.deepEqual(script.filter(entry => entry.op !== 'insert').map(entry => entry.line), a);
  assert.deepEqual(script.filter(entry => entry.op !== 'delete').map(entry => entry.line), b);
  assert.equal(script.filter(entry => entry.op !== 'equal').length, a.length + b.length - 2 * lcs(a, b));
  assert.deepEqual(diffLines(a, b), script);
  let insertion = false;
  for (const entry of script) {
    if (entry.op === 'equal') insertion = false;
    else if (entry.op === 'insert') insertion = true;
    else assert.equal(insertion, false, 'deletion follows insertion');
  }
  for (let context = 0; context <= 4; context++) {
    const hunks = unifiedHunks(a, b, { context });
    assert.deepEqual(hunks, expectedHunks(script, context));
    for (const hunk of hunks) { Object.freeze(hunk.lines); Object.freeze(hunk); }
    Object.freeze(hunks);
    assert.deepEqual(applyHunks(a, hunks), b);
  }
  assert.deepEqual(unifiedHunks(a, b), expectedHunks(script, 3));
  pairs++;
}
console.log(`Exhaustive minimality, determinism, ordering, hunk boundaries and roundtrips: ${pairs} pairs, contexts 0..4`);

const base = Object.freeze(['a', 'b', 'c', 'd']);
const valid = { oldStart: 2, oldLines: 1, newStart: 2, newLines: 2, lines: ['-b', '+B', '+extra'] };
assert.deepEqual(applyHunks(base, [valid]), ['a', 'B', 'extra', 'c', 'd']);
assert.deepEqual(applyHunks(base, [valid, { oldStart: 4, oldLines: 1, newStart: 4, newLines: 0, lines: ['-d'] }]), ['a', 'B', 'extra', 'c']);
const bad = [
  null, {}, { ...valid, oldStart: 0 }, { ...valid, oldStart: -1 },
  { ...valid, oldStart: 1.5 }, { ...valid, oldStart: NaN },
  { ...valid, oldStart: Infinity }, { ...valid, oldStart: '2' },
  { ...valid, oldLines: -1 }, { ...valid, oldLines: 2 },
  { ...valid, oldLines: 0 }, { ...valid, oldStart: 6 },
  { ...valid, newStart: 0 }, { ...valid, newStart: 3 },
  { ...valid, newLines: 1 }, { ...valid, newLines: -1 },
  { ...valid, lines: ['-wrong', '+B', '+extra'] },
  { ...valid, lines: [' wrong', '+extra'] },
  { ...valid, lines: ['', '+B', '+extra'] },
  { ...valid, lines: ['?b', '+B', '+extra'] },
  { ...valid, lines: [42, '+B', '+extra'] },
  { ...valid, lines: null },
];
for (const hunk of bad) assert.throws(() => applyHunks(base, [hunk]), /hunk 0 does not apply/);
for (const hunk of [
  { ...valid, newStart: 2 },
  { oldStart: 1, oldLines: 1, newStart: 1, newLines: 0, lines: ['-a'] },
  { oldStart: 4, oldLines: 1, newStart: 3, newLines: 0, lines: ['-d'] },
]) assert.throws(() => applyHunks(base, [valid, hunk]), /hunk 1 does not apply/);
const copy = applyHunks(base, []);
assert.deepEqual(copy, base);
assert.notEqual(copy, base);
console.log('Malformed counts, coordinates, ordering, prefixes and mismatches rejected with indexed errors');

for (const repetitive of [false, true]) {
  const a = Array.from({ length: 20000 }, (_, i) => repetitive ? 'same' : `line ${i}`);
  const b = a.slice();
  b.splice(0, 0, '+top');
  b.splice(10000, 1, '-replacement', '', '+addition');
  b.pop();
  const start = performance.now();
  const script = diffLines(a, b);
  const hunks = unifiedHunks(a, b);
  const result = applyHunks(a, hunks);
  const elapsed = performance.now() - start;
  assert.equal(script.filter(entry => entry.op !== 'equal').length, 6);
  assert.deepEqual(result, b);
  assert.ok(elapsed < 1000, `${elapsed}ms exceeds one second`);
  console.log(`20,000 ${repetitive ? 'repetitive' : 'distinct'} lines: diff + hunks + apply ${elapsed.toFixed(2)}ms`);
}
